import { useRouter } from 'next/navigation'
import { ArrowDownLeft, ArrowUpRight, Bell, CalendarDays, Check, ChevronDown, CircleHelp, CreditCard, LayoutDashboard, LogOut, Menu, MoreHorizontal, PiggyBank, Plus, Settings, SlidersHorizontal, TrendingUp, Wallet, X } from 'lucide-react'
import { archiveBudgetAllocationAction, archiveCategoryAction, createAccountAction, createAccountTransactionAction, createBudgetAllocationAction, createCategoryAction, createExpenseTemplateAction, createHouseholdInviteAction, initializeHouseholdAction, toggleExpenseTemplateAction, updateCategoryAction, updateIncomeTemplateAction, updateMonthlyExpenseAction, updateMonthlyIncomeAction } from '@/app/actions/finance'
import { signOutAction } from '@/app/actions/auth'
import { brl, currentDateBrazil, formatDate, monthLabel } from '@/lib/finance/types'
import type { Expense, FinanceData } from '@/lib/finance/types'

const navigation = [
  { label: 'Dashboard', icon: LayoutDashboard },
  { label: 'Pagamentos', icon: CalendarDays },
  { label: 'Planejamento', icon: SlidersHorizontal },
  { label: 'Contas & reservas', icon: PiggyBank },
  { label: 'Histórico', icon: TrendingUp },
  { label: 'Configurações', icon: Settings },
]
const money = (value: number | string | null | undefined) => brl(Number(value ?? 0))
const toCents = (value: number | string | null | undefined) => {
  const match = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(String(value ?? 0).trim().replace(',', '.'))
  if (!match) return 0
  const cents = Number(match[2]) * 100 + Number((match[3] ?? '').padEnd(2, '0'))
  return match[1] === '-' ? -cents : cents
}
const addMoney = (left: number, right: number) => (toCents(left) + toCents(right)) / 100
const total = (rows: Array<{ amount: number }>) => rows.reduce((sum, row) => sum + toCents(row.amount), 0) / 100
const statusLabels = { unpaid: 'Pendente', credit_card: 'No cartão', paid: 'Pago' }

